/**
 * RecallProofPreflight - operator-only GO/NO-GO board for the Recall proof.
 *
 * Reads GET /api/v1/admin/recall-proof/preflight (operator-gated, read-only)
 * and renders the current blockers before an operator spends the tightly gated
 * Recall proof run. The dedicated operator key is held in component state only:
 * never persisted to browser storage, cookies, URL params, or echoed.
 */
import { useState } from "react";
import GravitoShell from "@/components/gravito/GravitoShell";

interface PreflightBlocker {
  code: string;
  message: string;
}

interface PreflightWarning {
  code: string;
  message: string;
}

interface RecallCounters {
  counters?: {
    recallLookupCount?: number;
    recognizedRepeatFailureCount?: number;
    recallErrorCount?: number;
  };
  lastRecognizedAt?: string | null;
}

interface PreflightBody {
  ok: boolean;
  deployed_version: string;
  ready: boolean;
  checks: {
    operator_auth_satisfied: boolean;
    deployed_version_known: boolean;
    expected_sha: string | null;
    expected_sha_match: boolean | null;
    capture_flag_enabled: boolean;
    salt_present: boolean;
    database_reachable: boolean;
    pool_mode: "transaction_pooler" | "direct";
    prepared_statements_disabled: boolean;
    pool_max: number | null;
    proof_already_ran: boolean;
    capture_row_count: number | null;
    recall_proof_row_count: number | null;
    canary_state_for_sha: { exists: boolean; status: string | null } | null;
    recall_counters: RecallCounters;
  };
  blockers: PreflightBlocker[];
  warnings: PreflightWarning[];
}

type ViewState = "empty" | "loading" | "unauthorized" | "error" | "loaded";

const KEY_LINE =
  "This board reads readiness only. It never flips the capture flag, never runs /run, never calls /self-audit, and never writes a verdict.";

function yn(value: boolean | null | undefined): string {
  if (value === true) return "yes";
  if (value === false) return "no";
  return "-";
}

function value(v: string | number | null | undefined): string {
  return v === null || v === undefined || v === "" ? "-" : String(v);
}

function Badge({ tone, children }: { tone: "go" | "stop" | "warn" | "neutral"; children: string }) {
  const colors = {
    go: "var(--teal, #1ff0c0)",
    stop: "#f06464",
    warn: "#f0b45a",
    neutral: "rgba(255,255,255,.55)",
  };
  return (
    <span
      className="mono"
      style={{
        border: `1px solid ${colors[tone]}`,
        borderRadius: 999,
        color: colors[tone],
        display: "inline-flex",
        fontSize: 11,
        letterSpacing: ".08em",
        padding: "3px 9px",
        textTransform: "uppercase",
        whiteSpace: "nowrap",
      }}
    >
      {children}
    </span>
  );
}

function CheckRow({ label, children, ok }: { label: string; children: string; ok?: boolean | null }) {
  const tone = ok === true ? "go" : ok === false ? "stop" : "neutral";
  return (
    <div
      style={{
        alignItems: "center",
        borderTop: "1px solid rgba(255,255,255,.08)",
        display: "grid",
        gap: 12,
        gridTemplateColumns: "170px 1fr auto",
        padding: "10px 0",
      }}
    >
      <span className="mono" style={{ color: "rgba(255,255,255,.52)", fontSize: 11, letterSpacing: ".08em" }}>
        {label}
      </span>
      <span style={{ color: "var(--ink-2, rgba(255,255,255,.78))", fontSize: 14 }}>{children}</span>
      <Badge tone={tone}>{ok === null || ok === undefined ? "read" : ok ? "go" : "stop"}</Badge>
    </div>
  );
}

export default function RecallProofPreflight() {
  const [operatorKey, setOperatorKey] = useState("");
  const [expectedSha, setExpectedSha] = useState("");
  const [state, setState] = useState<ViewState>("empty");
  const [body, setBody] = useState<PreflightBody | null>(null);

  async function loadPreflight() {
    if (!operatorKey) {
      setState("empty");
      return;
    }
    setState("loading");
    setBody(null);
    try {
      const query = expectedSha.trim() ? `?expected_sha=${encodeURIComponent(expectedSha.trim())}` : "";
      const res = await fetch(`/api/v1/admin/recall-proof/preflight${query}`, {
        headers: { Authorization: "Bearer " + operatorKey },
      });
      if (res.status === 401) {
        setState("unauthorized");
        return;
      }
      if (!res.ok) {
        setState("error");
        return;
      }
      const json = (await res.json()) as PreflightBody;
      if (!json.ok || !json.checks) {
        setState("error");
        return;
      }
      setBody(json);
      setState("loaded");
    } catch {
      setState("error");
    }
  }

  const counters = body?.checks.recall_counters?.counters;

  return (
    <GravitoShell>
      <header className="section" style={{ paddingBottom: 0, paddingTop: "clamp(46px, 7vw, 88px)" }}>
        <div className="wrap">
          <span className="eyebrow">Admin · Recall proof preflight</span>
          <h1 style={{ fontSize: "clamp(30px, 4.4vw, 52px)", maxWidth: "18ch" }}>The proof gate, read before it runs.</h1>
          <p className="lede" style={{ maxWidth: "68ch" }}>
            Check the live conditions for the controlled Recall proof before any flag window opens. This page is
            operator-only, read-only, and exists to prevent guesswork.
          </p>
          <p className="caveat" style={{ marginTop: 12, maxWidth: "72ch" }}>
            {KEY_LINE}
          </p>
          <p className="caveat" style={{ marginTop: 12, maxWidth: "72ch" }}>
            Current memory:{" "}
            <a href="/admin/verdict-memory" style={{ color: "var(--teal, #1ff0c0)", textDecoration: "underline" }}>
              open the Verdict Memory viewer
            </a>{" "}
            to inspect the recorded verdicts before deciding whether the next proof is ready.
          </p>
          <p className="caveat" style={{ marginTop: 12, maxWidth: "72ch" }}>
            Full posture:{" "}
            <a href="/admin/governance-spine" style={{ color: "var(--teal, #1ff0c0)", textDecoration: "underline" }}>
              Governance Spine
            </a>{" "}
            for the honest Gate → Remember → Recall → Prevention roll-up.
          </p>

          <div style={{ display: "grid", gap: 12, marginTop: 24, maxWidth: 760 }}>
            <label className="mono" htmlFor="operator-key" style={{ color: "rgba(255,255,255,.6)", fontSize: 12 }}>
              Operator key
            </label>
            <input
              autoComplete="off"
              id="operator-key"
              onChange={(e) => setOperatorKey(e.target.value)}
              placeholder="dedicated operator key"
              type="password"
              value={operatorKey}
              style={{
                background: "rgba(255,255,255,.05)",
                border: "1px solid rgba(255,255,255,.16)",
                borderRadius: 10,
                color: "var(--ink, #fff)",
                fontSize: 14,
                padding: "10px 14px",
              }}
            />

            <label className="mono" htmlFor="expected-sha" style={{ color: "rgba(255,255,255,.6)", fontSize: 12 }}>
              Expected SHA (optional)
            </label>
            <input
              autoComplete="off"
              id="expected-sha"
              onChange={(e) => setExpectedSha(e.target.value)}
              placeholder="leave blank to read live deployed version"
              value={expectedSha}
              style={{
                background: "rgba(255,255,255,.05)",
                border: "1px solid rgba(255,255,255,.16)",
                borderRadius: 10,
                color: "var(--ink, #fff)",
                fontSize: 14,
                padding: "10px 14px",
              }}
            />

            <button
              className="btn btn-volt"
              disabled={!operatorKey || state === "loading"}
              onClick={() => {
                void loadPreflight();
              }}
              type="button"
              style={{ justifySelf: "start" }}
            >
              {state === "loading" ? "Checking..." : "Read preflight"}
            </button>
          </div>
        </div>
      </header>

      <section className="section">
        <div className="wrap">
          {state === "empty" && <p className="caveat">Enter the dedicated operator key, then read the current gate.</p>}
          {state === "loading" && <p className="caveat">Reading the live proof gate...</p>}
          {state === "unauthorized" && (
            <p className="caveat" style={{ color: "#f0b45a" }}>
              Key rejected. The dedicated operator key was not accepted; the key is not shown or stored.
            </p>
          )}
          {state === "error" && (
            <p className="caveat" style={{ color: "#f0b45a" }}>
              Could not read the preflight board. Try again after confirming the deployed endpoint is healthy.
            </p>
          )}

          {state === "loaded" && body && (
            <div style={{ display: "grid", gap: 20, maxWidth: 920 }}>
              <article
                style={{
                  background: body.ready ? "rgba(31,240,192,.06)" : "rgba(240,180,90,.05)",
                  border: `1px solid ${body.ready ? "rgba(31,240,192,.35)" : "rgba(240,180,90,.34)"}`,
                  borderRadius: 16,
                  padding: "18px 22px",
                }}
              >
                <div style={{ display: "flex", flexWrap: "wrap", gap: 12, justifyContent: "space-between" }}>
                  <div>
                    <p className="mono" style={{ color: "rgba(255,255,255,.55)", fontSize: 12, margin: 0 }}>
