                color: "var(--ink, #fff)",
                fontSize: 14,
                padding: "10px 14px",
              }}
            />

            <button
              className="btn btn-volt"
              disabled={!operatorKey || state === "loading"}
              onClick={() => {
                void loadPreflight();
              }}
              type="button"
              style={{ justifySelf: "start" }}
            >
              {state === "loading" ? "Checking..." : "Read preflight"}
            </button>
          </div>
        </div>
      </header>

      <section className="section">
        <div className="wrap">
          {state === "empty" && <p className="caveat">Enter the dedicated operator key, then read the current gate.</p>}
          {state === "loading" && <p className="caveat">Reading the live proof gate...</p>}
          {state === "unauthorized" && (
            <p className="caveat" style={{ color: "#f0b45a" }}>
              Key rejected. The dedicated operator key was not accepted; the key is not shown or stored.
            </p>
          )}
          {state === "error" && (
            <p className="caveat" style={{ color: "#f0b45a" }}>
              Could not read the preflight board. Try again after confirming the deployed endpoint is healthy.
            </p>
          )}

          {state === "loaded" && body && (
            <div style={{ display: "grid", gap: 20, maxWidth: 920 }}>
              <article
                style={{
                  background: body.ready ? "rgba(31,240,192,.06)" : "rgba(240,180,90,.05)",
                  border: `1px solid ${body.ready ? "rgba(31,240,192,.35)" : "rgba(240,180,90,.34)"}`,
                  borderRadius: 16,
                  padding: "18px 22px",
                }}
              >
                <div style={{ display: "flex", flexWrap: "wrap", gap: 12, justifyContent: "space-between" }}>
                  <div>
                    <p className="mono" style={{ color: "rgba(255,255,255,.55)", fontSize: 12, margin: 0 }}>
                      deployed {body.deployed_version}
                    </p>
                    <h2 style={{ fontSize: 28, margin: "8px 0 0" }}>{body.ready ? "GO-ready" : "Not ready"}</h2>
                  </div>
                  <Badge tone={body.ready ? "go" : "stop"}>{body.ready ? "go" : "no-go"}</Badge>
                </div>
              </article>

              <article style={{ border: "1px solid rgba(255,255,255,.12)", borderRadius: 16, padding: "18px 22px" }}>
                <CheckRow label="AUTH" ok={body.checks.operator_auth_satisfied}>
                  operator auth satisfied: {yn(body.checks.operator_auth_satisfied)}
                </CheckRow>
                <CheckRow label="VERSION" ok={body.checks.deployed_version_known}>
                  known: {yn(body.checks.deployed_version_known)} · expected match: {yn(body.checks.expected_sha_match)}
                </CheckRow>
                <CheckRow label="CAPTURE FLAG" ok={body.checks.capture_flag_enabled}>
                  enabled: {yn(body.checks.capture_flag_enabled)}
                </CheckRow>
                <CheckRow label="SALT" ok={body.checks.salt_present}>
                  present: {yn(body.checks.salt_present)}
                </CheckRow>
                <CheckRow label="DATABASE" ok={body.checks.database_reachable}>
                  reachable: {yn(body.checks.database_reachable)} · pool: {body.checks.pool_mode} · pool max:{" "}
                  {value(body.checks.pool_max)}
                </CheckRow>
                <CheckRow label="PREPARED STMT" ok={body.checks.prepared_statements_disabled}>
                  disabled: {yn(body.checks.prepared_statements_disabled)}
                </CheckRow>
                <CheckRow label="PROOF STATE" ok={!body.checks.proof_already_ran}>
                  already ran: {yn(body.checks.proof_already_ran)} · recall rows: {value(body.checks.recall_proof_row_count)} ·
                  total capture rows: {value(body.checks.capture_row_count)}
                </CheckRow>
                <CheckRow label="CANARY STATE" ok={body.checks.canary_state_for_sha?.exists === false}>
                  {body.checks.canary_state_for_sha
                    ? `exists: ${yn(body.checks.canary_state_for_sha.exists)} · status: ${value(body.checks.canary_state_for_sha.status)}`
                    : "unavailable"}
                </CheckRow>
                <CheckRow label="RECALL COUNTERS" ok={(counters?.recallErrorCount ?? 0) === 0}>
                  lookup {value(counters?.recallLookupCount)} · recognized {value(counters?.recognizedRepeatFailureCount)} · errors{" "}
                  {value(counters?.recallErrorCount)}
                </CheckRow>
              </article>

              {(body.blockers.length > 0 || body.warnings.length > 0) && (
                <article style={{ border: "1px solid rgba(255,255,255,.12)", borderRadius: 16, padding: "18px 22px" }}>
                  {body.blockers.length > 0 && (
                    <>
                      <h2 style={{ fontSize: 22, margin: "0 0 10px" }}>Blockers</h2>
                      <div style={{ display: "grid", gap: 10 }}>
                        {body.blockers.map((blocker) => (
                          <p key={blocker.code} className="caveat" style={{ color: "#f0b45a", margin: 0 }}>
                            {blocker.code}: {blocker.message}
                          </p>
                        ))}
                      </div>
                    </>
                  )}
                  {body.warnings.length > 0 && (
                    <>
                      <h2 style={{ fontSize: 22, margin: body.blockers.length > 0 ? "20px 0 10px" : "0 0 10px" }}>Warnings</h2>
                      <div style={{ display: "grid", gap: 10 }}>
                        {body.warnings.map((warning) => (
                          <p key={warning.code} className="caveat" style={{ margin: 0 }}>
                            {warning.code}: {warning.message}
                          </p>
                        ))}
                      </div>
                    </>
                  )}
                </article>
              )}
            </div>
          )}
        </div>
      </section>
    </GravitoShell>
  );
}

